CREATE OR REPLACE FUNCTION public.validate_locker() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer;BEGIN
IF NEW.type NOT IN('Individual Locker','Double-door Locker','Multi-compartment Locker','Shared Locker','Custom Locker') OR NEW.status NOT IN('Available','Allocated','Under Maintenance','Damaged','Decommissioned') OR NEW.condition NOT IN('Good','Needs Repair','Damaged') OR NEW.capacity<1 OR btrim(NEW.number)='' THEN RAISE EXCEPTION 'Invalid locker details'; END IF;
IF NEW.type<>'Shared Locker' AND NEW.capacity<>1 THEN RAISE EXCEPTION 'Only shared lockers may hold multiple employees'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.buildings WHERE id=NEW.block_id AND camp_id=NEW.camp_id) OR NOT(EXISTS(SELECT 1 FROM public.block_floors WHERE building_id=NEW.block_id AND floor_number=NEW.floor) OR EXISTS(SELECT 1 FROM public.rooms WHERE building_id=NEW.block_id AND floor=NEW.floor)) OR (NEW.room_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.rooms WHERE id=NEW.room_id AND camp_id=NEW.camp_id AND building_id=NEW.block_id AND floor=NEW.floor)) THEN RAISE EXCEPTION 'Locker location does not match saved infrastructure'; END IF;
SELECT count(*) INTO n FROM public.locker_allocations WHERE locker_id=NEW.id AND released_on IS NULL;
IF TG_OP='UPDATE' AND n>0 AND (NEW.status IN('Available','Decommissioned') OR NEW.camp_id<>OLD.camp_id OR NEW.block_id<>OLD.block_id OR NEW.floor<>OLD.floor OR NEW.room_id IS DISTINCT FROM OLD.room_id OR NEW.capacity<n OR NEW.type IS DISTINCT FROM OLD.type) THEN RAISE EXCEPTION 'Release allocations before changing location, type or availability'; END IF;
IF NEW.status='Allocated' AND n=0 THEN RAISE EXCEPTION 'Use Allocate Locker'; END IF;
IF NEW.status='Available' AND NEW.condition<>'Good' THEN RAISE EXCEPTION 'Only usable lockers can be available'; END IF;
RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.validate_locker_event_date() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.effective_date>CURRENT_DATE THEN RAISE EXCEPTION 'Future locker events not allowed';END IF;RETURN NEW;END $$;
CREATE TRIGGER locker_event_validate BEFORE INSERT ON public.locker_events FOR EACH ROW EXECUTE FUNCTION public.validate_locker_event_date();
CREATE OR REPLACE FUNCTION public.audit_locker_charge() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.locker_events(locker_id,allocation_id,kind,effective_date,actor,new_value,remarks) SELECT locker_id,NEW.allocation_id,'Charge Transaction',NEW.effective_date,NEW.actor,to_jsonb(NEW),NEW.remarks FROM public.locker_allocations WHERE id=NEW.allocation_id; RETURN NEW;END $$;
CREATE TRIGGER locker_charge_audit AFTER INSERT ON public.locker_charge_transactions FOR EACH ROW EXECUTE FUNCTION public.audit_locker_charge();